PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?taxon ?taxonLabel WHERE {
  # Classes related to animals in space
  {
    ?spaceClass wdt:P279 wd:Q2621143 .   # subclass of animal in space
  }
  UNION
  {
    ?spaceClass wdt:P31 wd:Q2621143 .    # instance of animal in space (if any classes)
  }

  # Follow subclass-of chain upwards
  ?spaceClass wdt:P279* ?taxon .

  # Keep only non-human animal taxa or classes
  FILTER(?taxon != wd:Q5).

  # Either a taxon or a subclass of animal
  {
    ?taxon wdt:P31 wd:Q16521 .          # instance of taxon
  }
  UNION
  {
    ?taxon wdt:P279 wd:Q729 .           # subclass of animal
  }

  OPTIONAL { ?taxon rdfs:label ?taxonLabel FILTER(LANG(?taxonLabel) = "en") }
}

